  return '<div class="grp '+(st==="open"?"sev-"+g.sevKey:"st-"+st)+'">'+head(g,st,g.sev)+kvHtml(g.kv)+
    (g.msgs.length?'<ul class="msgs">'+g.msgs.map(function(m){ return '<li>'+esc(m)+'</li>'; }).join("")+(g.moreMsgs?'<li>+'+g.moreMsgs+' more</li>':'')+'</ul>':'')+
    '<ul class="hist">'+hist.map(function(h){ return '<li>'+esc(h)+'</li>'; }).join("")+'</ul>'+
    '<div class="acts">'+actsFor(g,st)+(g.billId?'<span class="spacer"></span><button class="btn link" data-open="'+esc(g.billId)+'">Open bill '+esc(g.billId)+'</button>':'')+'</div>'+
    (draft===g.key?flagForm(g.key):'')+'</div>';
}

// Pairs identical on every bill are the issue's context; the rest are per bill.
function split(groups){
  var first=groups[0].kv, common=[];
  first.forEach(function(p){ if(groups.every(function(g){ return g.kv.some(function(q){ return q[0]===p[0]&&String(q[1])===String(p[1]); }); })) common.push(p); });
  var ck={}; common.forEach(function(p){ ck[p[0]]=true; });
  return {common:common, own:function(g){ return g.kv.filter(function(p){ return !ck[p[0]]; }); }};
}
function issue(groups){
  var g0=groups[0], sp=split(groups);
  var sts=groups.map(statusOf), open_=groups.filter(function(g,i){ return sts[i]==="open"; });
  var st=sts.indexOf("flag")>=0?"flag":(open_.length?"open":(sts.every(function(x){ return x==="res"; })?"res":"ack"));
  var sevV=Math.max.apply(null,groups.map(function(g){ return g.sev; }));
  var bulk=open_.length?'<button class="btn'+(g0.todo==="accept"?" pri":"")+'" data-act="ackall">Acknowledge all '+open_.length+' open</button>'+
                        '<button class="btn flag'+(g0.todo==="escalate"?" pri":"")+'" data-act="flagall">⚑ Flag all '+open_.length+' open</button>':'';
  var rows=groups.map(function(g,i){
    var s=sts[i], own=sp.own(g), bill=own.filter(function(p){ return p[0]==="Bill"; })[0], per=own.filter(function(p){ return p[0]==="Service period"; })[0];
    var isOpen=!!expanded[g.key], hist=[g.raised].concat(sess().log[g.key]||[]);
    return '<div class="brow st-'+s+'"><div class="bline"><button class="tw" data-tw="'+esc(g.key)+'">'+(isOpen?"▾":"▸")+'</button>'+
      '<span class="bt num">'+esc(bill?bill[1]:("Bill "+(g.billId||"")))+'</span><span class="bs num">'+esc(per?per[1]:"")+'</span>'+chip(s)+
      '<span class="spacer"></span>'+actsFor(g,s,true)+'</div>'+
      (isOpen?'<div class="bdet">'+kvHtml(own.filter(function(p){ return p[0]!=="Bill"&&p[0]!=="Service period"; }))+
        (g.msgs.length?'<ul class="msgs">'+g.msgs.map(function(m){ return '<li>'+esc(m)+'</li>'; }).join("")+'</ul>':'')+
        '<ul class="hist">'+hist.map(function(h){ return '<li>'+esc(h)+'</li>'; }).join("")+'</ul>'+
        (g.billId?'<div class="acts"><button class="btn link" data-open="'+esc(g.billId)+'">Open bill '+esc(g.billId)+'</button></div>':'')+'</div>':'')+
      (draft===g.key?flagForm(g.key):'')+'</div>';
  }).join("");
  return '<div class="grp '+(st==="open"?"sev-"+g0.sevKey:"st-"+st)+'">'+head(g0,st,sevV,'<span class="chip">'+groups.length+' bills</span>')+
    kvHtml(sp.common)+(bulk?'<div class="acts">'+bulk+'</div>':'')+(draft==="*all"?flagForm("*all","Flag all "+open_.length+" open"):'')+
    '<div class="bills">'+rows+'</div></div>';
}

function render(){
  var root=document.getElementById("root"); if(!root) return;
  var p=M.popup;
  if(!p||!p.groups||!p.groups.length){ root.innerHTML='<div class="wrap"><div class="mh"><b>Validation error</b><button class="x" id="close">×</button></div><div class="empty">Nothing selected.</div></div>'; bind(); return; }
  var byCode={}, order=[];
  p.groups.forEach(function(g){ if(!byCode[g.code]){ byCode[g.code]=[]; order.push(g.code); } byCode[g.code].push(g); });
  var body=order.map(function(c){ return byCode[c].length>1?issue(byCode[c]):single(byCode[c][0]); }).join("");
  var title=order.length===1&&byCode[order[0]].length>1?byCode[order[0]].length+" bills with the same error":p.title;
  root.innerHTML='<div class="wrap"><div class="mh"><b>'+esc(title)+'</b><button class="x" id="close" title="Close">×</button></div>'+
    '<div class="mb"><div class="note">Prototype: Acknowledge and Flag are kept for this page visit only and are not saved to UBM.</div>'+body+'</div></div>';
  bind();
}

function groupOf(key){ return ((M.popup||{}).groups||[]).filter(function(g){ return g.key===key; })[0]; }
function send(p){ appsmith.updateModel({errorAction:p}); appsmith.triggerEvent("onErrorAction",{errorAction:p}); }
function payload(kind,gs){
  var ids=[]; gs.forEach(function(g){ ids=ids.concat(g.ids); });
  return {action:kind, groupKey:gs[0].key, groupKeys:gs.map(function(g){ return g.key; }), errorIds:ids, code:gs[0].code,
          recordIds:gs.map(function(g){ return g.recordId; }), billIds:gs.map(function(g){ return g.billId; }),
          recordId:gs[0].recordId, billId:gs[0].billId,
          customerId:M.popup.customerId, locationId:M.popup.locationId, accounts:gs[0].accounts};
}
function openGroups(){ return M.popup.groups.filter(function(g){ return statusOf(g)==="open"; }); }
function action(kind,key){
  if(kind==="flag"){ draft=key; render(); return; }
  if(kind==="flagall"){ draft="*all"; render(); return; }
  if(kind==="cancel"){ draft=null; render(); return; }
  if(kind==="ackall"){ var og=openGroups(); if(og.length) send(payload("acknowledge",og)); return; }
  var gs=key==="*all"?openGroups():[groupOf(key)].filter(Boolean);
  if(!gs.length) return;
  var p=payload(kind,gs);
  if(kind==="escalate"){
    var sel=document.getElementById("flagto");
    p.assigneeId=sel&&sel.value?Number(sel.value):null;
    p.assigneeName=sel?sel.options[sel.selectedIndex].text:"";
    p.note=(document.getElementById("flagnote")||{}).value||""; draft=null;
  }
  send(p);
}
function bind(){
  var c=document.getElementById("close"); if(c) c.onclick=function(){ draft=null; expanded={}; appsmith.triggerEvent("onClose"); };
  document.getElementById("root").onclick=function(e){
    var t=e.target; if(!t.closest) return;
    var tw=t.closest("[data-tw]"); if(tw){ var k=tw.getAttribute("data-tw"); expanded[k]=!expanded[k]; render(); return; }
    var a=t.closest("[data-act]"); if(a){ action(a.getAttribute("data-act"),a.getAttribute("data-g")); return; }
    var o=t.closest("[data-open]"); if(o){ var id=o.getAttribute("data-open"); appsmith.updateModel({pickedBill:id}); appsmith.triggerEvent("onOpenBill",{pickedBill:id}); }
  };
}
function tick(){
  try{
    var m=(window.appsmith&&appsmith.model)||{}, s=JSON.stringify(m);
    // do not redraw under someone typing a flag note
    var typing=draft&&document.activeElement&&/^(TEXTAREA|SELECT)$/.test(document.activeElement.tagName);
    if(s!==lastModel&&!typing){
      var keysOf=function(x){ return JSON.stringify(((x||{}).groups||[]).map(function(g){ return g.key; })); };
      if(keysOf(M.popup)!==keysOf(m.popup)){ draft=null; expanded={}; }
      lastModel=s; M=m; render();
    }
  }catch(e){}
}
tick(); setInterval(tick,300);
